# Based on Cortex-A78 Software Optimization Guide
# s3.6 Divide and multiply instructions

# Divide, W-form
sdiv	w0, w1, w2
udiv	w0, w1, w2

# Divide, X-form
sdiv	x0, x1, x2
udiv	x0, x1, x2

# Multiply
mul	w0, w1, w2
mul	x0, x1, x2
mneg	w0, w1, w2
mneg	x0, x1, x2

# Multiply accumulate, W-form
madd     w0, w1, w2, w3
msub     w0, w1, w2, w3

# Multiply accumulate, X-form
madd     x0, x1, x2, x3
msub     x0, x1, x2, x3

# Multiply accumulate long
smaddl   x0, w1, w2, x3
smsubl   x0, w1, w2, x3
umaddl   x0, w1, w2, x3
umsubl   x0, w1, w2, x3

# Multiply high
smulh    x0, x1, x2
umulh    x0, x1, x2

# Multiply long
smnegl   x0, w1, w2
smull   x0, w1, w2
umnegl   x0, w1, w2
umull   x0, w1, w2

